import {getTerminalDetail, addTerminal, updateTerminal} from "@/api/terminal";
import {mapGetters} from "vuex";

export default {
  data() {
    return {
      id: '',
      form: {
        ip: "",
        status: "",
        mac: "",
        gateway: "",
      },
      loading: true,
      isEdit: true,
      deviceStatusList:[{
        label: '1',
        value: '在线'
      },{
        label: '0',
        value: '离线'
      }],
      btnLoading: false,
    };
  },
  computed: {
    ...mapGetters(["permission"]),
    permissionList() {
      return {
        addBtn: this.vaildData(this.permission.deviceRecord_add, false),
        viewBtn: this.vaildData(this.permission.deviceRecord_view, false),
        delBtn: this.vaildData(this.permission.deviceRecord_delete, false),
        editBtn: this.vaildData(this.permission.deviceRecord_edit, false),
        exportBtn: this.vaildData(this.permission.deviceRecord_export, false)
      };
    },
  },
  async mounted() {
    // 设置页面元素高度
    this.setPageContentHeight()
    this.id = null;
    //获取参数 判断是否是新增还是修改
    const params = this.$route.query
    //params.id='1760851395719598082'
    this.id = params.id || '';
    if (params.id) {
      this.id = params.id;
      this.loadDetail(params.id);
      this.isEdit = true
    } else {
      //加载空数据
      this.beforeOpen();
      this.isEdit = true
    }
  },
  methods: {
    async handleSaveOK() {
      this.$refs.dataForm.validate(async (valid) => {
        if (valid) {
          this.btnLoading = true //按钮加载状态
          let saveRes = this.id ? await updateTerminal(this.form) : await addTerminal(this.form)
          if (saveRes[0] != null) {
            this.btnLoading = false
            return
          }
          this.btnLoading = false
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          this.handleReset();
        }
      })
    },
    handleReset() {
      //返回
      this.$closePage('/device/devRecord');
    },
    beforeOpen() {
      getEmpty().then(res => {
        this.form = res.data;
        this.form.id = null;
        this.$forceUpdate()
      });
    },
    loadDetail(id) {
      getTerminalDetail(id).then(res => {
        this.form = res.data;
        this.$refs.dataForm.$forceUpdate()
        this.$forceUpdate()
      });
    },
  }
};
